// Writes MANIFEST.json for the frozen S11 fixtures: sha-256 per file, the sentinel
// high-risk areas each file covers, how it was made, and (for the pptx) what the
// Lectern adapter reads out of it. The M0 pptx read-direction mapping itself is M2; M0
// only freezes the file and records these read-outs.
//   node tests/fixtures/clioworks-s11/manifest.mjs
import vm from "node:vm";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import AdmZip from "adm-zip";
import { makeContext, loadScripts } from "./vm-context.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const sha = (buf) => createHash("sha256").update(buf).digest("hex");
const FILES = ["budget-s11.xlsx", "lossless-negative-s11.xlsx", "slides-notes-comment-s11.pptx", "quire-s11.docx"];
const bytesOf = (name) => readFileSync(join(here, name));

async function ledgerReadout(name) {
  const ctx = makeContext();
  loadScripts(ctx, ["app/vendor/clioworks-v3/ledger-adapter.js"]);
  ctx.__bytes = new Uint8Array(bytesOf(name));
  const ledger = await vm.runInContext("ClioWorksLedgerAdapter.open(globalThis.__bytes, { name: 'x.xlsx' })", ctx);
  const sheets = ledger.sheets().map((s) => s.name);
  const formulaCells = ledger.listCells(sheets[0]).filter((c) => typeof c.cell.f === "string").length;
  const saved = await ledger.save();
  return { sheets, formulaCells, saveWithoutEdit: saved.mode };
}

async function quireReadout(name) {
  const ctx = makeContext();
  loadScripts(ctx, ["app/vendor/clioworks-v3/quire-adapter.js"]);
  ctx.__bytes = new Uint8Array(bytesOf(name));
  const doc = await vm.runInContext("ClioWorksQuireAdapter.open(globalThis.__bytes, { name: 'x.docx' })", ctx);
  const paragraphs = doc.paragraphs();
  const level = (n) => paragraphs.filter((p) => p.headingLevel === n).length;
  const lists = (kind) => paragraphs.filter((p) => p.list && p.list.kind === kind).length;
  const flag = (k) => paragraphs.reduce((n, p) => n + p.runs.filter((r) => r[k]).length, 0);
  return {
    paragraphs: paragraphs.length,
    headings: { 1: level(1), 2: level(2), 3: level(3) },
    bulletParagraphs: lists("bullet"), numberedParagraphs: lists("number"),
    tables: doc.tables().length,
    images: paragraphs.reduce((n, p) => n + p.runs.filter((r) => r.kind === "image").length, 0),
    comments: doc.comments().length,
    boldRuns: flag("b"), italicRuns: flag("i"), underlineRuns: flag("u"),
    saveWithoutEdit: (await doc.save()).mode,
  };
}

async function lecternReadout(name) {
  const ctx = makeContext();
  loadScripts(ctx, ["app/vendor/clioworks-v3/lectern-adapter.js"]);
  ctx.__bytes = new Uint8Array(bytesOf(name));
  const deck = await vm.runInContext("ClioWorksLecternAdapter.open(globalThis.__bytes, { name: 'x.pptx' })", ctx);
  const pages = deck.slideCount();
  const notes = [];
  for (let i = 0; i < pages; i += 1) notes.push(deck.notes(i).length > 0);
  const modelComments = deck.presentation().slides.reduce((n, sl) => n + ((sl.keep && sl.keep.comments) || []).length, 0);
  const zip = new AdmZip(bytesOf(name));
  const commentParts = zip.getEntries().filter((e) => /^ppt\/comments\/.*\.xml$/.test(e.entryName));
  let commentRefs = 0;
  for (const e of commentParts) commentRefs += (e.getData().toString("utf8").match(/<p:cm\b/g) || []).length;
  const rels = zip.getEntries().filter((e) => /^ppt\/slides\/_rels\/.*\.rels$/.test(e.entryName))
    .reduce((n, e) => n + (e.getData().toString("utf8").match(/relationships\/comments"/g) || []).length, 0);
  return {
    pages, notesPages: notes.filter(Boolean).length, commentParts: commentParts.length,
    commentRecordsInModel: modelComments, commentCountInXml: commentRefs, slideCommentRelationships: rels,
    losses: deck.losses().map((l) => ({ id: l.id, action: l.action, notify: !!l.notify })),
    saveWithoutEdit: (await deck.save()).mode,
  };
}

const meta = {
  "quire-s11.docx": {
    covers: ["headings-1-3", "character-styles", "bullet-and-numbered-lists", "table-read-only", "image-read-only", "existing-comment"],
    detail: {
      "headings-1-3": "Heading1 搬家清单, Heading2 先装箱, Heading3 再叫车 (styles carry outlineLvl)",
      "character-styles": "one paragraph with plain, bold, italic and underline runs",
      "bullet-and-numbered-lists": "numId 1 (bullet) x2, numId 2 (decimal) x2",
      "table-read-only": "one 2x2 TableGrid table (项目/数量, 纸箱/20)",
      "image-read-only": "one inline 1x1 PNG (word/media/image1.png) in a paragraph with text",
      "existing-comment": "comment 0 by 阿澄 on 纸箱, range + reference, word/comments.xml",
    },
    source: "generated by generate-docx.mjs (synthetic, hand-written OOXML, adm-zip, fixed timestamps)",
  },
  "budget-s11.xlsx": {
    covers: ["shared-formula", "number-format", "cached-values", "five-cell-states"],
    detail: {
      "shared-formula": "预算!D2:D10 (si=0, master D2) and G2:G8 (si=1, master G2)",
      "number-format": "custom \"¥\"#,##0, 0.0%, yyyy\"年\"m\"月\"d\"日\", builtin 14",
      "cached-values": "every formula carries <v>; D9 caches #VALUE!, F12 caches a string",
      "five-cell-states": "empty C9, zero B10, text-not-measured B9, formula error D9, formula number D2",
    },
    source: "generated by generate.mjs (synthetic, hand-written OOXML, adm-zip, fixed timestamps)",
  },
  "lossless-negative-s11.xlsx": {
    covers: ["LOSSLESS_SAVE-known-loss:ledger-smartart", "shared-formula", "number-format", "cached-values"],
    detail: {
      "LOSSLESS_SAVE-known-loss": "sheet 预算 carries a SmartArt graphicFrame (xl/drawings/drawing1.xml + xl/diagrams/*). Upstream LOSSLESS_SAVE.md 'To do' 1: Ledger drops SmartArt on a sheet entirely. Observed here: the preserving writer reports it only as unreferenced:* entries with action=drop and notify=false, and the saved sheet no longer references the drawing.",
    },
    source: "same workbook as budget-s11.xlsx plus a drawing with one SmartArt frame; generated by generate.mjs",
    knownLoss: {
      expectedDroppedParts: [
        "xl/diagrams/colors1.xml", "xl/diagrams/data1.xml", "xl/diagrams/layout1.xml", "xl/diagrams/quickStyle1.xml", "xl/drawings/drawing1.xml",
      ],
      note: "negative regression input (S11-C9): while the upstream defect stands the first-save list must count these as 转换或丢失 even though notify=false; if upstream fixes it, update this entry.",
    },
  },
  "slides-notes-comment-s11.pptx": {
    covers: ["speaker-notes", "existing-comment"],
    detail: { "speaker-notes": "notesSlide1/2 inherited from creator-slides.pptx", "existing-comment": "one legacy p:cm on slide 1 by 阿澄 (commentAuthors.xml)" },
    source: "derived by generate.mjs from tests/fixtures/clioworks-v4/creator-slides.pptx (adds commentAuthors.xml + comments/comment1.xml + 3 package edits)",
  },
};

const files = [];
for (const name of FILES) {
  const buf = bytesOf(name);
  const entry = { name, sha256: sha(buf), bytes: buf.length, ...meta[name] };
  entry.adapterReadout = name.endsWith(".xlsx") ? await ledgerReadout(name) : name.endsWith(".docx") ? await quireReadout(name) : await lecternReadout(name);
  files.push(entry);
}
writeFileSync(join(here, "MANIFEST.json"), JSON.stringify({
  schema: "clioworks-s11-fixtures/1",
  milestone: "S11-M0",
  generator: "generate.mjs",
  servedCopies: "apps/desktop/app/vendor/clioworks-v3/fixture-files/ (xlsx and quire-s11.docx; generate.mjs / generate-docx.mjs write them, the contract asserts equal sha-256)",
  files,
}, null, 2) + "\n");
console.log("MANIFEST.json written for", FILES.join(", "));
